sys_script_client.script:
function onSubmit() {
	//MSSCUSTODY-3942
    // Verify if reason description has <>
    var reasonDesc = g_form.getValue('corresponding_switch_trade_reason_description');
    g_form.hideFieldMsg("corresponding_switch_trade_reason_description");
    if (reasonDesc.toString().indexOf('<') != -1 || reasonDesc.toString().indexOf('>') != -1) {
        g_form.showFieldMsg("corresponding_switch_trade_reason_description","Unable to submit, please update Reason Description to populate <xxx> section. Note that <> are also special characters which cannot be submitted.", "error" );
        return false;
    }
 // Verify if reason description contains special characeters which are not accepted
    var RegularExp = /^[a-zA-Z0-9/\-?:().,'+\s]*$/i;
    var result = RegularExp.test(reasonDesc.toString());
    if (result == false) {
        g_form.showFieldMsg("corresponding_switch_trade_reason_description","Unable to submit. Special Characters are not permitted, please update the Reason Description using only Alphanumeric characters or /-?: ().,’+ or space.", "error");

        return false;
    }


}
